args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?deathDate WHERE {
  VALUES ?film { dbr:Ridin'_Pretty dbr:How_Strange_to_Be_Named_Federico }
  ?film dbo:director ?dir .
  OPTIONAL { ?dir dbo:deathDate ?death1 . }
  OPTIONAL { ?dir dbp:death_date ?death2 . }
  OPTIONAL { ?dir dbp:deathDate ?death3 . }
  BIND(COALESCE(?death1, ?death2, ?death3) AS ?deathRaw)
  FILTER(BOUND(?deathRaw))
  BIND(xsd:date(str(?deathRaw)) AS ?deathDate)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = "en") }
}
ORDER BY DESC(?deathDate)
LIMIT 1

